 communityShareText(){const room=this.state?.communityRoom;if(!room?.shareUrl)return'';let when='';if(room.startMode==='scheduled'&&room.startsAt){const d=new Date(room.startsAt);if(Number.isFinite(d.getTime()))when=`\n🕘 ${d.toLocaleString('es-AR',{weekday:'short',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}`;}const modeLine=this.state?.antibingo?.enabled?'\n☠ ANTIBINGO · ÚLTIMO CARTÓN VIVO GANA · NO HAGAS BINGO':this.state?.flash?.enabled?'\n⚡ MODO FLASH · 1 cartón · 10 bolas':this.state?.championship?.enabled?'\n🏆 CAMPEONATO LA GORDA':'';return `🎱 Te invito a jugar Bingo\n${room.name||'Sala pública'}${when}${modeLine}\nEntrá acá: ${room.shareUrl}`}
