    choices=this.mini.ended?'<button data-mini-restart="1" class="waitingMiniWide">VOLVER A JUGAR</button>':'<button data-mini-choice="higher">↑ MAYOR</button><button data-mini-choice="lower">↓ MENOR</button>';
