 async playMini(choice){if(this.mini.ended||this.mini.busy||this.state?.status!=='waiting'||!['red_black','higher_lower'].includes(this.mini.type))return;this.mini.busy=true;const next=this.randomMiniCard(),type=this.mini.type;let correct=false,tie=false;if(type==='red_black')correct=choice===next.color;else{const current=this.mini.current||this.randomMiniCard();tie=next.value===current.value;correct=tie||(choice==='higher'?next.value>current.value:next.value<current.value)}this.mini.current=next;if(tie){this.mini.message=`Empate: salió ${next.rank}${next.symbol}. La racha sigue.`;this.mini.busy=false;this.renderWaiting();return}if(correct){this.mini.score++;this.recordMiniBest(this.mini.score);this.mini.message=type==='red_black'?`¡Correcto! Salió ${next.rank}${next.symbol}. Elegí otra vez.`:`¡Correcto! Salió ${next.rank}${next.symbol}. ¿Mayor o menor?`;this.mini.busy=false;this.renderWaiting();this.submitMiniScore(type,this.mini.bestByType[type]);return}this.mini.ended=true;this.mini.message=`Salió ${next.rank}${next.symbol}. Racha final: ${this.mini.score}.`;this.recordMiniBest(this.mini.score);this.mini.busy=false;this.renderWaiting();this.submitMiniScore(type,this.mini.bestByType[type])}
