 renderFinished(){const s=this.state,p=s.player,wins=this.finalWinnerEntries(),ownWins=Array.isArray(p.confirmedPrizes)?p.confirmedPrizes:[],drawn=s.game?.drawn||[],integrity=s.integrity||{},demo=Boolean(s.demo?.active),room=s.communityRoom||null,rematch=room?.rematch||null,wa=String(s.roomSettings?.whatsapp||'').replace(/\D/g,''),ownText=ownWins.map(w=>`${w.prizeLabel||labels[w.type]||w.type} · Cartón ${w.cardNumber}`).join(' / '),helpWaText=ownWins.length?`Hola, soy ${p.name}. Sala ${s.roomCode}. Tengo una jugada ganadora confirmada (${ownText}) y quiero hacer una consulta sobre la partida.`:`Hola, soy ${p.name}. Sala ${s.roomCode}. Necesito hacer una consulta sobre la partida.`,helpWaHref=wa?`https://wa.me/${wa}?text=${encodeURIComponent(helpWaText)}`:'';let finishMessage=demo?'Podés empezar otra demostración cuando quieras.':ownWins.length?'¡Felicitaciones! Tenés una jugada ganadora confirmada en esta partida.':'La partida terminó.';let primaryAction='<button id="finalPlayAgain" class="btn primary finalPlayAgain" type="button">🎮 JUGAR DE NUEVO</button>';if(rematch?.available){const seconds=Math.max(0,Math.ceil(Number(rematch.remainingMs||0)/1000)),minutes=Math.max(1,Math.ceil(seconds/60));finishMessage+=` Esta sala queda abierta unos ${minutes} min por si quieren jugar otra.`;if(rematch.ready&&!rematch.isCreator)primaryAction='<button id="finalPlayAgain" class="btn secondary finalPlayAgain" type="button" disabled>✓ ANOTADO PARA OTRA</button>';else primaryAction=`<button id="finalPlayAgain" class="btn primary finalPlayAgain" type="button">${rematch.isCreator?'▶ JUGAR OTRA PARTIDA':'QUIERO JUGAR OTRA'}</button>`;}else if(!demo)finishMessage+=' Podés volver a Comunidad para buscar la próxima.';$('root').innerHTML=`<div class="finalScreen"><section class="finalHero"><img src="/assets/logo.webp" alt="EL BINGO DE LA GORDA" title="Volver a Comunidad" style="cursor:pointer" onclick="location.href='/comunidad?quedar=1'"><span class="finalKicker">PARTIDA FINALIZADA</span><h1>Gracias por jugar, ${esc(p.name)}.</h1><p>${finishMessage}</p></section>${!demo&&helpWaHref?`<div class="finalContactHelp"><a class="btn secondary" href="${helpWaHref}" target="_blank" rel="noopener">WHATSAPP · CONSULTAR</a></div>`:''}${this.finalWinnerTickerMarkup(wins)}<div class="finalPrimary">${primaryAction}${!demo&&rematch?.available?'<a class="btn secondary" href="/comunidad">VOLVER A COMUNIDAD</a>':''}${demo?'<a class="btn secondary" href="/comunidad">🌐 COMUNIDAD</a>':''}</div><div class="finalTools"><button id="finalNumbers" class="finalTool" type="button"><b>#</b><span>NÚMEROS<br>SALIDOS</span></button><a class="finalTool" href="${esc(this.apiUrl('/api/player/acta.pdf'))}"><b>📄</b><span>ACTA<br>PDF</span></a><a class="finalTool" href="${esc(this.apiUrl('/api/player/integrity.txt'))}"><b>✓</b><span>SELLO<br>SHA-256</span></a></div><div class="finalSummary"><span>${drawn.length} / ${s.game?.mode||0} bolillas</span><span>${wins.length} jugada${wins.length===1?'':'s'} ganadora${wins.length===1?'':'s'} confirmada${wins.length===1?'':'s'}</span>${integrity.verified===true?'<span>✓ Sorteo verificado</span>':''}</div></div>`;$('finalNumbers').onclick=()=>this.openNumbers();if($('finalPlayAgain')&&!$('finalPlayAgain').disabled)$('finalPlayAgain').onclick=()=>rematch?.available?this.communityRematch():this.playAgain();this.setupFinalWinnerTicker(wins);this.syncChatDock();this.renderChat()}
 voiceTime(ms){const total=Math.max(0,Math.ceil(Number(ms||0)/1000)),m=Math.floor(total/60),sec=String(total%60).padStart(2,'0');return `${m}:${sec}`}
 voiceMessageMarkup(m){const id=/^voice_[a-f0-9]{24}$/.test(String(m?.audioId||''))?String(m.audioId):'',ext=/^(webm|ogg|mp4|mp3|aac)$/.test(String(m?.audioExt||''))?String(m.audioExt):'';if(!id||!ext)return'<span class="muted">Audio no disponible</span>';const role=m.voiceRole==='admin'?'ADMIN':m.voiceRole==='creator'?'CREADOR':'VOZ',duration=this.voiceTime(m.durationMs||0),src=`/chat-audio/${encodeURIComponent(id)}.${encodeURIComponent(ext)}`;return `<span class="voiceMessage voicePlayer" data-voice-id="${esc(id)}" data-voice-src="${esc(src)}" data-voice-duration="${Math.max(0,Number(m.durationMs)||0)}"><span class="voicePlayerMain"><button class="voicePlayBtn" type="button" data-voice-play aria-label="Reproducir audio">▶</button><input class="voiceSeek" data-voice-seek type="range" min="0" max="1000" value="0" aria-label="Progreso del audio"><span class="voiceTime" data-voice-time>0:00</span></span><small>🎙 ${esc(role)} · ${esc(duration)}</small></span>`}
 chatMessageBody(m,helper){if(m?.type==='audio')return this.voiceMessageMarkup(m);return helper?helper.renderMessage(m):esc(m?.text||'')}
