 openChat(){const panel=$('chatPanel');if(this.chatDockMode==='mobile'){this.setChatSheet('peek');this.renderChat();return}this.chatOpen=true;panel.classList.remove('hidden');$('chatFab').classList.add('hidden');const messages=this.state?.chat?.messages||[];this.lastChatId=messages.at(-1)?.id||this.lastChatId;$('chatCount').classList.add('hidden');this.renderChat();try{$('chatInput').focus({preventScroll:true})}catch{}}
